WITH r AS (
  SELECT rating, AVG(length) AS a FROM film WHERE length IS NOT NULL GROUP BY rating
),
b AS (
  SELECT AVG(length) AS base FROM film WHERE length IS NOT NULL
),
k1 AS (
  SELECT r.rating, r.a FROM r, b WHERE r.a > b.base
),
m AS (
  SELECT AVG(a) AS M FROM k1
),
k2 AS (
  SELECT k1.rating, k1.a FROM k1, m WHERE k1.a > m.M
)
SELECT AVG(k2.a), AVG(k2.a - b.base), AVG(k2.a - m.M)
FROM k2, b, m;
WITH r AS (
  SELECT rating, AVG(length) AS a FROM film WHERE length IS NOT NULL GROUP BY rating
),
b AS (
  SELECT AVG(length) AS base FROM film WHERE length IS NOT NULL
),
s1 AS (
  SELECT r.rating, r.a FROM r, b WHERE r.a > b.base
),
m AS (
  SELECT AVG(a) AS mean1 FROM s1
),
s2 AS (
  SELECT s1.rating, s1.a FROM s1, m WHERE s1.a > m.mean1
)
SELECT
  AVG(s2.a) AS F,
  AVG(s2.a - b.base) AS mean_diff_baseline,
  AVG(s2.a - (SELECT AVG(a) FROM s2)) AS mean_diff_F
FROM s2, b;
